<script>
import generalMixin from "../../mixins/general";
export default {
  name: "TrainingLanding",
  mixins: [generalMixin],
  props: ["queries"],

  data() {
    return {
      isHR: false,
      isHOD: false,
      accessLoading: true,
    };
  },

  computed: {
    basePath() {
      return this.queries?.path || "";
    },
  },

  async created() {
    this.accessLoading = true;
    await this.$nextTick();
    await new Promise((r) => setTimeout(r, 400));
    if (!this.queries.practitioner) {
      this.queries.practitioner = this.$store.state.user.obj.resource.extension
        .find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference"
          );
        })
        ?.valueReference?.reference?.split("/")?.[1];
    }

    await this.$nextTick();

    // Wait for generalMixin to finish loading user data
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        console.warn("Timeout waiting for user data to load");
        resolve();
      }, 15000);
    });

    await this.checkAccess();
  },

  methods: {
    async checkAccess() {
      this.accessLoading = true;
      try {
        const practitionerId =
          this.loggedInStaff && this.loggedInStaff.practitioner;
        if (!practitionerId) return;

        const [hrResp, hodResp] = await Promise.all([
          fetch("/site/general/getHR/" + practitionerId),
          fetch("/site/general/getHOD/" + practitionerId),
        ]);

        if (hrResp.ok) {
          const hrList = await hrResp.json();
          const hrMatch = Array.isArray(hrList)
            ? hrList.find((h) => h.practitioners.includes(practitionerId))
            : null;
          this.isHR = !!hrMatch;
        }

        if (hodResp.ok) {
          const hodList = await hodResp.json();
          const hodMatch = Array.isArray(hodList)
            ? hodList.find((h) => h.practitioners.includes(practitionerId))
            : null;
          this.isHOD = !!hodMatch;
        }
      } catch (err) {
        console.error("checkAccess error:", err);
      } finally {
        this.accessLoading = false;
      }
    },

    navigate(route, extraParams = {}) {
      const params = new URLSearchParams({
        path: this.basePath,
        practitioner: this.queries?.practitioner || "",
        ...extraParams,
      });
      window.location.href = `${route}?${params}`;
    },
  },
};
</script>

